import { beforeEach, describe, expect, it } from "vitest";

import { engagementSignals } from "../src/fixtures";
import {
  _resetStoreForTests,
  computeActivityScores,
  getActivityScore,
} from "../src/scoring";

beforeEach(() => {
  _resetStoreForTests();
});

describe("computeActivityScores", () => {
  it("computes weightedV1 scores correctly for a period", () => {
    computeActivityScores("weightedV1", "2026-01", engagementSignals);

    expect(getActivityScore("dave", "2026-01", "weightedV1")?.score).toBeCloseTo(30);
    expect(getActivityScore("elle", "2026-01", "weightedV1")?.score).toBeCloseTo(7.5);
    expect(getActivityScore("carol", "2026-01", "weightedV1")?.score).toBeCloseTo(21);
  });

  it("computes weightedV2 scores correctly for the same period, ranking users differently", () => {
    computeActivityScores("weightedV2", "2026-01", engagementSignals);

    expect(getActivityScore("dave", "2026-01", "weightedV2")?.score).toBeCloseTo(15);
    expect(getActivityScore("elle", "2026-01", "weightedV2")?.score).toBeCloseTo(30);
    expect(getActivityScore("carol", "2026-01", "weightedV2")?.score).toBeCloseTo(29);

    // Same raw data, same period -- but v1 ranks dave (30) > carol (21) > elle (7.5),
    // while v2 ranks elle (30) > carol (29) > dave (15). Whichever formula you
    // ask about, you need to get ITS answer back, not whichever formula
    // happened to run most recently.
  });

  it("does not destroy weightedV1's result for a period when weightedV2 is run afterward", () => {
    computeActivityScores("weightedV1", "2026-01", engagementSignals);
    const before = getActivityScore("dave", "2026-01", "weightedV1")?.score;

    computeActivityScores("weightedV2", "2026-01", engagementSignals);

    const after = getActivityScore("dave", "2026-01", "weightedV1")?.score;
    expect(after).toBeCloseTo(30);
    expect(after).toBe(before);
  });

  it("lets you retrieve what EITHER formula said about a period after both have been run", () => {
    computeActivityScores("weightedV1", "2026-02", engagementSignals);
    computeActivityScores("weightedV2", "2026-02", engagementSignals);

    expect(getActivityScore("carol", "2026-02", "weightedV1")?.score).toBeCloseTo(36);
    expect(getActivityScore("carol", "2026-02", "weightedV2")?.score).toBeCloseTo(30);
  });

  it("re-running the SAME formula for a period updates only that formula's record", () => {
    computeActivityScores("weightedV1", "2026-01", engagementSignals);
    computeActivityScores("weightedV2", "2026-01", engagementSignals);

    // Simulates a corrected/re-run nightly job for v1 -- should update v1's
    // own record without touching v2's already-computed record.
    computeActivityScores("weightedV1", "2026-01", engagementSignals);

    expect(getActivityScore("dave", "2026-01", "weightedV1")?.score).toBeCloseTo(30);
    expect(getActivityScore("dave", "2026-01", "weightedV2")?.score).toBeCloseTo(15);
  });

  it("returns undefined for a (user, period, formula) combination that was never computed", () => {
    computeActivityScores("weightedV1", "2026-01", engagementSignals);

    expect(getActivityScore("dave", "2026-02", "weightedV1")).toBeUndefined();
    expect(getActivityScore("dave", "2026-01", "weightedV2")).toBeUndefined();
  });

  it("keeps both periods' results independently retrievable across formulas", () => {
    computeActivityScores("weightedV1", "2026-01", engagementSignals);
    computeActivityScores("weightedV2", "2026-01", engagementSignals);
    computeActivityScores("weightedV1", "2026-02", engagementSignals);
    computeActivityScores("weightedV2", "2026-02", engagementSignals);

    expect(getActivityScore("elle", "2026-01", "weightedV1")?.score).toBeCloseTo(7.5);
    expect(getActivityScore("elle", "2026-01", "weightedV2")?.score).toBeCloseTo(30);
    expect(getActivityScore("elle", "2026-02", "weightedV1")?.score).toBeCloseTo(12);
    expect(getActivityScore("elle", "2026-02", "weightedV2")?.score).toBeCloseTo(41);
  });
});
